const fs = require('fs');

function solve() {
  const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
  if (data.length === 0) return;

  const n = parseInt(data[0], 10);
  const arr = data.slice(1, 1 + n);

  const freq = new Map();
  for (const s of arr) {
    freq.set(s, (freq.get(s) || 0) + 1);
  }

  let ans = 0;

  for (const s of arr) {
    const substrings = new Set();
    const len = s.length;

    for (let i = 0; i < len; i++) {
      for (let j = i + 1; j <= len; j++) {
        substrings.add(s.slice(i, j));
      }
    }

    let total = 0;
    for (const sub of substrings) {
      total += freq.get(sub) || 0;
    }

    ans += total - 1;
  }

  console.log(ans);
}

solve();
